<?= $this->section('scripts') ?><script>
$(function () { $('#hair-analysis-patient-link').on('submit', function (event) { event.preventDefault(); var form = $(this), button = form.find('button'); button.prop('disabled', true); $.ajax({ url: '<?= base_url('admin/integrations/shopify/ai-hair-analysis/leads/' . (int) $lead['id'] . '/link-patient') ?>', method: 'POST', data: form.serialize(), headers: { 'X-Requested-With': 'XMLHttpRequest' }, success: function (response) { if (response.status) { window.location.reload(); } else { window.alert(response.msg || 'The patient could not be linked.'); } }, error: function (xhr) { var response = xhr.responseJSON || {}; window.alert(response.msg || 'The patient could not be linked safely.'); }, complete: function () { button.prop('disabled', false); } }); }); });
</script><script>$(function () { $('#hair-analysis-patient-create').on('submit', function (event) { event.preventDefault(); var form = $(this), button = form.find('button'); button.prop('disabled', true); $.ajax({ url: '<?= base_url('admin/integrations/shopify/ai-hair-analysis/leads/' . (int) $lead['id'] . '/create-patient') ?>', method: 'POST', data: form.serialize(), headers: { 'X-Requested-With': 'XMLHttpRequest' }, success: function (response) { if (response.status) window.location.reload(); else window.alert(response.msg || 'Patient creation failed.'); }, error: function (xhr) { var response = xhr.responseJSON || {}; window.alert(response.msg || 'Patient could not be created safely.'); }, complete: function () { button.prop('disabled', false); } }); }); });</script><?php if ((string) $lead['status'] === 'failed'): ?><script>$(function () { $('#hair-analysis-retry').on('click', function () { var button = $(this); button.prop('disabled', true).text('Retrying…'); $.ajax({ url: '<?= base_url('admin/integrations/shopify/ai-hair-analysis/leads/' . (int) $lead['id'] . '/retry') ?>', method: 'POST', headers: { 'X-Requested-With': 'XMLHttpRequest' }, data: { '<?= csrf_token() ?>': '<?= csrf_hash() ?>' }, success: function (response) { if (response.status) window.location.reload(); else window.alert(response.msg || 'Retry failed.'); }, error: function (xhr) { var response = xhr.responseJSON || {}; window.alert(response.msg || 'Retry failed safely.'); }, complete: function () { button.prop('disabled', false).text('Retry analysis'); } }); }); });</script><?php endif; ?><?= $this->endSection() ?>
